export function getAllDoctors(): Doctor[] {
  return doctors
}

export function getDoctorBySlug(slug: string): Doctor | undefined {
  return doctors.find(d => d.slug === slug)
}

export function getDoctorsByCity(citySlug: string): Doctor[] {
  return doctors.filter(d => d.citySlug === citySlug)
}

export function getDoctorsBySpeciality(specialitySlug: string): Doctor[] {
  return doctors.filter(d => d.specialitySlug === specialitySlug)
}

export function getDoctorsByCityAndSpeciality(citySlug: string, specialitySlug: string): Doctor[] {
  return doctors.filter(d => d.citySlug === citySlug && d.specialitySlug === specialitySlug)
}

export function getAllDoctorSlugs(): string[] {
  return doctors.map(d => d.slug)
}

export function getDoctorsForDisease(specialitySlug: string, citySlug?: string): Doctor[] {
  let result = doctors.filter(d => d.specialitySlug === specialitySlug)
  if (citySlug) result = result.filter(d => d.citySlug === citySlug)
  return result.sort((a, b) => b.experience - a.experience).slice(0, 4)
}
